import type BaseComponent from "../../common/base-component"
import DecisionContent from "../../pages/decision-content/decision-content"
import PickingContent from "../../pages/picking-content/picking-content"
import { Pages } from "../../routes/pages"
import type { TPages } from "../../routes/pages"
import Router from "../../routes/router"

import { View } from "../view"

const enum CSSClasses {
  WRAPPER = "wrapper",
  MAIN = "main",
}

export default class MainView extends View {
  protected router: Router
  constructor() {
    const parameters = {
      tag: "main",
      classNames: [CSSClasses.WRAPPER, CSSClasses.MAIN],
    }
    super(parameters)
    this.router = new Router()
  }

  public setContent(component: HTMLElement | BaseComponent): void {
    this.destroyChildren()
    this.appendChildComponent(component)
  }

  public getPage(): TPages[] {
    const decisionContent = new DecisionContent(this.router)
    const pickingContent = new PickingContent(this.router)

    const pages = [
      {
        name: Pages.INDEX,
        callback: (): void => this.setContent(decisionContent),
      },
      {
        name: Pages.DECISION,
        callback: (): void => this.setContent(pickingContent),
      },
    ]

    return pages
  }
}
